from typing import TypedDict

class Bid(TypedDict):
    name: str
    price: int

def lower(offer: int, standing: int) -> bool:
    return not (offer > standing)

def winner(incumbent: Bid, challenger: Bid) -> Bid:
    if lower(challenger["price"], incumbent["price"]):
        return challenger
    return incumbent

