def nearest(value: int) -> int:
    base = abs(value) // 10
    if value < 0:
        base = -base
    magnitude = abs(value - 10 * base)
    if magnitude < 5:
        return base
    step = 1
    if value < 0:
        step = -1
    if magnitude > 5:
        return base + step
    return on_half(base, step)

def on_half(base: int, step: int) -> int:
    if base % 2 == 0:
        return base + step
    return base

